using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using SchoolERP.Api.Security;using SchoolERP.Application.Features.Subjects;using SchoolERP.Domain.Security;using SchoolERP.Shared.Models;namespace SchoolERP.Api.Controllers.v1;[ApiController,Authorize,Route("api/v1/classes/{classId:guid}/subjects")]public sealed class ClassSubjectsController(ISubjectService s):ControllerBase{[HttpGet,RequirePermission(PermissionCatalog.Subject.View)]public async Task<ActionResult<ApiResponse<IReadOnlyCollection<ClassSubjectDto>>>>List(Guid classId,CancellationToken ct)=>Ok(ApiResponse<IReadOnlyCollection<ClassSubjectDto>>.Ok(await s.GetClassSubjectsAsync(classId,ct)));[HttpPut,RequirePermission(PermissionCatalog.Subject.ManageClassMapping)]public async Task<IActionResult>Set(Guid classId,SetClassSubjectsRequest r,CancellationToken ct){await s.SetClassSubjectsAsync(classId,r,ct);return NoContent();}[HttpPost("{subjectId:guid}"),RequirePermission(PermissionCatalog.Subject.ManageClassMapping)]public async Task<IActionResult>Assign(Guid classId,Guid subjectId,ClassSubjectAssignmentRequest r,CancellationToken ct){await s.AssignAsync(classId,subjectId,r,ct);return NoContent();}[HttpDelete("{subjectId:guid}"),RequirePermission(PermissionCatalog.Subject.ManageClassMapping)]public async Task<IActionResult>Remove(Guid classId,Guid subjectId,CancellationToken ct){await s.RemoveAsync(classId,subjectId,ct);return NoContent();}}
